// Tuned via XShade (http://www.funparadigm.com/xshade/)

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    float t = iTime+5.;
	float z = 6.;

	const int n = 100; // particle count

    vec3 startColor = vec3(0.6,0.6,0.2);
	vec3 endColor = vec3(0.06,0.64,0.85);

	float startRadius = 0.84;
	float endRadius = 1.6;

	float power = 0.45;
	float duration = 4.;

	vec2
		s = iResolution.xy,
		v = z*(2.*gl_FragCoord.xy-s)/s.y;

    // Mouse axis y => zoom
	if(iMouse.z>0.) v *= iMouse.y/s.y * 20.;

    // Mouse axis x => duration
	if(iMouse.z>0.) duration = iMouse.x/s.x * 10.;

	vec3 col = vec3(0.);

	vec2 pm = v.yx*2.8;

	float dMax = duration;

    //original evo
    //float evo = (sin(iTime*.01+400.)*.5+.5)*99.+1.;

    //custom evo
    vec4 a = vec4(TAU*2.0, TAU, HALFPI*2.0, HALFPI/2.0);
    // Define the interval for each multiplication and total duration
    float totalDuration = dMax * 4.0; // 4 seconds * 4 elements
    // Calculate the elapsed time
    float timeInSequence = min(iTime, totalDuration); // Clamp to the total duration
    // Determine the current index (0, 1, 2, or 3), or use the last value when time exceeds
    int index = int(timeInSequence / dMax);
    // Prevent index from going out of bounds
    if (index >= 3)
        index = 3; // Use the last element in `a` once the sequence is done
    float evo = (rsin(iTime*.01+400.)*.5+.5)*a[index]+1.;

    float mb = 0.;
	float mbRadius = 0.;
	float sum = 0.;
	for(int i=0;i<n;i++)
	{
        //float d = fract(t*power+48934.4238*sin(float(i/int(evo))*692.7398));
        float d = fract(t*power+48934.4238* rsin( fract(HALFPI*float(i/int(evo)) )*692.7398));

        float dt = float(i)/float(n);
        vec2 sc = radPosAt(dt, fract(dt*4.0)*4.0);
        float x = d*sc.x*duration;
        float y = d*sc.y*duration;

		float distRatio = (d/dMax);

		mbRadius = mix(startRadius, endRadius, distRatio);

		vec2 p = v - vec2(x,y);//*vec2(1,sin(a+1.57));

		mb = mbRadius/dot(p,p);

		sum += mb;

		col = mix(col, mix(startColor, endColor, distRatio), mb/sum);
	}

	sum /= float(n);

	col = normalize(col) * sum;

	sum = clamp(sum, 0., .4);

	vec3 tex = vec3(1.);

	col *= smoothstep(tex, vec3(0.), vec3(sum));

	fragColor.rgb = col;
}

//Credit to John Gabriel for the rsin and rcos formulas here
//The parameters are called "radical unit angles".
//https://www.scribd.com/document/801842032/Ancient-Greek-Formulas

#define HALFPI 1.57079632679489661923
#define TAU (HALFPI*4.0)

// Radical sine approximation (optimized)
float rsin(float x) {
    float a = 1.0 - 2.0 * x + 2.0 * x * x;
    float invSqrtA = inversesqrt(a);
    return x * invSqrtA;
}

// Radical cosine approximation (optimized)
float rcos(float x) {
    float a = 1.0 - 2.0 * x + 2.0 * x * x;
    float invSqrtA = inversesqrt(a);
    return (1.0 - x) * invSqrtA;
}

// Quadrant logic (branchless)
vec2 getQuadrant(int quadrant, float c, float s) {
    /*   -x,+y  |  +x,+y
        ___q2___|___q3____
         -x,-y  |  +x,-y
           q1   |    q0    */

    // 1 if even, 0 if odd
    float qEven = 1.0 - float(quadrant & 1);
    // 1 if first two quadrants, 0 otherwise
    float qFirstHalf = 1.0 - float(quadrant >= 2);

    // Swap c and s based on quadrant parity
    float x = mix(s, c, qEven);
    float y = mix(c, s, qEven);

    // Flip y for upper/lower halves
    y *= mix(-1.0, 1.0, qFirstHalf);
    // Flip x for left/right halves
    x *= mix(-1.0, 1.0, float(quadrant == 0 || quadrant == 3)); 

    return vec2(x, y);
}

// Optimized radical-based trig position
vec2 radPosAt(float param, float quadrantCount) {
    int quadrant = int(mod(quadrantCount, 4.0));
    return getQuadrant(quadrant, rcos(param), rsin(param));
}
